#ifndef DECL_BASE_HPP
#define DECL_BASE_HPP

#include<string>
#include<vector>

#include"visitorsBase.hpp"
#include"parser.hpp"

class Scope;

// Base class for all declarations generated by the code executor (Builder class)
class Declaration
{
private:
    std::string name;
protected:
    explicit Declaration(std::string _name) : name(std::move(_name)) {}
public:
    std::string getName() const { return name; }
    virtual void accept(DeclarationVisitor& visitor) const = 0;
    virtual ~Declaration() = default;
};

// Base class for all declarations that elicit a value
class ValueDeclaration : public Declaration 
{
public:
    using Declaration::Declaration;
    virtual RuntimeValue getValue() const = 0;
    virtual void setValue(const RuntimeValue& val) = 0;
    virtual std::string getType() const = 0;
};

class ObjectDeclaration : public Declaration
{
public:
    void accept(DeclarationVisitor& visitor) const override { visitor.visit(*this); }
    std::shared_ptr<Scope> member_scope;
    std::string type_name;

    explicit ObjectDeclaration(std::string _name,
        std::shared_ptr<Scope> _member_scope,
        std::string t) :
        Declaration(_name), member_scope(std::move(_member_scope)), type_name(std::move(t)) {}

};

// Function declaration class 
// The function's body is implemented as a vector of raw pointers to AST nodes 
// so that when you call the function the nodes are executed
//
// The function's arguments are similarly raw pointers to declarations
// that are "declared" when the function is called
//
// There are no lifetime issues with the raw pointers because the 
// entire AST lives in main.cpp and lasts for the duration of the program
class FunctionDeclaration : public Declaration
{
private:
    std::size_t num_args;
    std::vector<std::string> arg_names;
    std::string return_type;
    
public:
    std::vector<ASTNode*> body_nodes;
    std::vector<DeclarationNode*> arg_nodes;
    std::shared_ptr<Scope> declaration_scope;

public:
    void accept(DeclarationVisitor& visitor) const override { visitor.visit(*this); }

    std::vector<std::string> getArgNames() const { return arg_names; }
    std::size_t getNumArgs() const { return num_args; }
    std::string getReturnType() const { return return_type; }

    explicit FunctionDeclaration(   std::string _name, 
                                    std::size_t _num_args,
                                    std::vector<std::string> _arg_names,
                                    std::string _return_type,
                                    std::vector<ASTNode*> _body_nodes,
                                    std::vector<DeclarationNode*> _args,
                                    std::shared_ptr<Scope> _declaration_scope
                                ) : Declaration(_name), 
                                    num_args(_num_args), 
                                    arg_names(_arg_names),
                                    return_type(std::move(_return_type)),
                                    body_nodes( _body_nodes ),
                                    arg_nodes(_args),
                                    declaration_scope(std::move(_declaration_scope)) {}
};

#endif